package com.picviewer.app;
import org.junit.*;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import com.picviewer.core.Photo;import com.picviewer.core.Scanner;
public class SmbIntegrationTest {
 Config config(){Config c=new Config();c.host="127.0.0.1";c.port=Integer.parseInt(System.getenv("PICVIEWER_TEST_PORT"));c.user=System.getenv("PICVIEWER_TEST_USER");c.password=System.getenv("PICVIEWER_TEST_PASSWORD");c.share="photos";return c;}
 @Before public void requireServer(){Assume.assumeNotNull(System.getenv("PICVIEWER_TEST_PORT"));}
 @Test public void authenticatedReadOnlyScanAndFetch()throws Exception{try(SmbSource s=new SmbSource(config())){s.connect();Scanner.Result r=Scanner.scan(s,"",Collections.emptyList(),Collections.emptySet(),new AtomicBoolean(),null);assertTrue(r.complete());assertTrue(r.photos.stream().anyMatch(p->p.path.equals("여행/하위/사진2.jpg")));assertTrue(r.photos.stream().anyMatch(p->p.path.equals("일상/사진10.png")));assertEquals(4,r.photos.size());File tmp=File.createTempFile("picviewer",".jpg");try{s.fetch("여행/하위/사진2.jpg",tmp,1024*1024);assertTrue(tmp.length()>10);assertEquals(0xff,Files.readAllBytes(tmp.toPath())[0]&255);}finally{tmp.delete();}}}
 @Test public void incorrectPasswordRejected()throws Exception{Config c=config();c.password="intentionally-wrong-fixture-password";try(SmbSource s=new SmbSource(c)){try{s.connect();fail("wrong password accepted");}catch(Exception e){assertEquals("AUTH",SmbSource.kind(e));}}}
 @Test public void downloadLimitAborts()throws Exception{try(SmbSource s=new SmbSource(config())){File tmp=File.createTempFile("limit",".part");try{try{s.fetch("여행/하위/사진2.jpg",tmp,5);fail();}catch(Exception e){assertEquals("LIMIT",SmbSource.kind(e));}}finally{tmp.delete();}}}
 @Test public void rescanRemovesOnlyConfirmedDeletes()throws Exception{try(SmbSource s=new SmbSource(config())){Scanner.Result first=Scanner.scan(s,"",Collections.emptyList(),Collections.emptySet(),new AtomicBoolean(),null);java.nio.file.Path root=Paths.get(System.getenv("PICVIEWER_TEST_ROOT"));java.nio.file.Path file=root.resolve("mutable/new.jpg");Files.createDirectories(file.getParent());Files.write(file,new byte[]{1,2,3});Scanner.Result added=Scanner.scan(s,"",first.photos,first.folders,new AtomicBoolean(),null);assertEquals(first.photos.size()+1,added.photos.size());Files.delete(file);Scanner.Result removed=Scanner.scan(s,"",added.photos,added.folders,new AtomicBoolean(),null);assertEquals(first.photos.size(),removed.photos.size());}}
 @Test public void staleMetadataDoesNotCacheUnderOldVersion()throws Exception{try(SmbSource s=new SmbSource(config())){File tmp=File.createTempFile("stale",".part");try{try{s.fetch("여행/하위/사진2.jpg",tmp,1024*1024,1,1);fail();}catch(IOException e){assertTrue(e.getMessage().contains("FILE_CHANGED_SINCE_SCAN"));}}finally{tmp.delete();}}}
}
